TITLE Passive Leak Membrane Conductance

NEURON {
  SUFFIX pas_leak
  NONSPECIFIC_CURRENT i
  RANGE g, e, i
}

PARAMETER {
  g = 0.0003 (S/cm2) <0, 1e9>
  e = -65.0 (mV)
}

ASSIGNED {
  v (mV)
  i (mA/cm2)
}

BREAKPOINT {
  i = g * (v - e)
}

TITLE Dual-Exponential Excitatory AMPA Synapse

NEURON {
  SUFFIX alpha_syn
  NONSPECIFIC_CURRENT i
  RANGE gmax, tau_r, tau_d, e, g, i
}

PARAMETER {
  gmax = 0.002 (uS) <0, 1e9>
  tau_r = 0.5 (ms) <0.01, 100>
  tau_d = 5.0 (ms) <0.1, 500>
  e = 0.0 (mV)
}

STATE {
  A
  B
}

ASSIGNED {
  v (mV)
  g (uS)
  i (nA)
}

INITIAL {
  A = 0.0
  B = 0.0
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  g = gmax * (B - A)
  i = g * (v - e)
}

DERIVATIVE states {
  A' = -A / tau_r
  B' = -B / tau_d
}

TITLE L-Type Calcium Channel with GHK Permeation

NEURON {
  SUFFIX cal_ghk
  USEION ca READ cai, cao WRITE ica
  RANGE pbar, gca, ica
  GLOBAL minf, hinf, mtau, htau
}

PARAMETER {
  pbar = 0.00015 (cm/s) <0, 1e9>
  cai = 0.0001 (mM)
  cao = 2.0 (mM)
  eca = 120.0 (mV)
}

STATE {
  m
  h
}

ASSIGNED {
  v (mV)
  gca (S/cm2)
  ica (mA/cm2)
}

INITIAL {
  m = 0.02
  h = 0.85
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  gca = pbar * (m^2) * h
  ica = gca * (v - eca)
}

DERIVATIVE states {
  m' = (minf - m) / mtau
  h' = (hinf - h) / htau
}

